<?php
$source='https://www2.census.gov/geo/docs/maps-data/data/gazetteer/2026_Gazetteer/2026_Gaz_place_national.zip';
$zipPath=sys_get_temp_dir().'/flighttimingusa_places.zip';$dir=sys_get_temp_dir().'/flighttimingusa_places_'.uniqid();
echo "Downloading 2026 Census National Places Gazetteer...\n";
if(function_exists('curl_init')){$ch=curl_init($source);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_TIMEOUT=>120]);$data=curl_exec($ch);$status=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($data===false||$status>=400){fwrite(STDERR,'Download failed: HTTP '.$status."\n");exit(1);}}else{$data=@file_get_contents($source);if($data===false){fwrite(STDERR,"Download failed. Enable cURL or allow_url_fopen.\n");exit(1);}}
file_put_contents($zipPath,$data);$zip=new ZipArchive();if($zip->open($zipPath)!==true){fwrite(STDERR,"Invalid Census ZIP.\n");exit(1);}mkdir($dir,0777,true);$zip->extractTo($dir);$zip->close();$files=glob($dir.'/*.txt');if(!$files){fwrite(STDERR,"No TXT file found.\n");exit(1);}
$fh=fopen($files[0],'r');$header=trim(fgets($fh));$cols=array_map('trim',preg_split('/\|/',$header));$idx=array_flip($cols);foreach(['NAME','GEOID','USPS','INTPTLAT','INTPTLONG'] as $need)if(!isset($idx[$need])){fwrite(STDERR,'Missing field: '.$need."\n");exit(1);}
$out=[];$seen=[];while(($line=fgets($fh))!==false){$p=preg_split('/\|/',trim($line));if(count($p)<count($cols))continue;$name=trim($p[$idx['NAME']]);$state=trim($p[$idx['USPS']]);$lat=(float)$p[$idx['INTPTLAT']];$lon=(float)$p[$idx['INTPTLONG']];$geoid=trim($p[$idx['GEOID']]);if($name===''||$state===''||($lat===0.0&&$lon===0.0))continue;$base=preg_replace('/\s+(city|town|village|borough|municipality|CDP)$/i','',$name);$ascii=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$base.'-'.$state);$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$ascii),'-'));if(isset($seen[$slug]))$slug.=$geoid;$seen[$slug]=true;$out[]=['name'=>$base.', '.$state,'state_code'=>$state,'lat'=>$lat,'lon'=>$lon,'slug'=>$slug,'geoid'=>$geoid];}
fclose($fh);usort($out,fn($a,$b)=>strcmp($a['name'],$b['name']));file_put_contents(__DIR__.'/../data/cities.php',"<?php\nreturn ".var_export($out,true).";\n");echo 'Generated '.count($out)." Census places.\n";